import Foundation

public enum PacketType: UInt8 {
    case handshake = 0
    case handshakeAck = 1
    case frameHeader = 2
    case frameChunk = 3
    case cursorUpdate = 4
    case inputEvent = 5
    case control = 6
    case ping = 7
    case audioFrame = 8
}

public struct PacketHeader {
    public let magic: UInt16
    public let type: PacketType
    public let sequence: UInt32
    public let timestamp: UInt32
    public let flags: UInt8

    public init(type: PacketType, sequence: UInt32, timestamp: UInt32, flags: UInt8 = 0) {
        self.magic = ERDConstants.magic
        self.type = type
        self.sequence = sequence
        self.timestamp = timestamp
        self.flags = flags
    }

    public func serialize() -> Data {
        var data = Data(capacity: ERDConstants.packetHeaderSize)
        var m = magic.littleEndian; data.append(Data(bytes: &m, count: 2))
        var t = type.rawValue;      data.append(Data(bytes: &t, count: 1))
        var s = sequence.littleEndian; data.append(Data(bytes: &s, count: 4))
        var ts = timestamp.littleEndian; data.append(Data(bytes: &ts, count: 4))
        var f = flags;              data.append(Data(bytes: &f, count: 1))
        return data
    }

    public static func deserialize(from data: Data) -> PacketHeader? {
        guard data.count >= ERDConstants.packetHeaderSize else { return nil }
        let magic = data.subdata(in: 0..<2).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        guard magic == ERDConstants.magic else { return nil }
        guard let type = PacketType(rawValue: data[2]) else { return nil }
        let seq = data.subdata(in: 3..<7).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let ts = data.subdata(in: 7..<11).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let flags = data[11]
        return PacketHeader(type: type, sequence: seq, timestamp: ts, flags: flags)
    }
}

import Foundation

public struct FrameHeaderPayload {
    public let frameId: UInt32
    public let width: UInt16
    public let height: UInt16
    public let isKeyFrame: Bool
    public let totalChunks: UInt16
    public let totalSize: UInt32

    public static let size = 16

    public init(frameId: UInt32, width: UInt16, height: UInt16, isKeyFrame: Bool, totalChunks: UInt16, totalSize: UInt32) {
        self.frameId = frameId; self.width = width; self.height = height
        self.isKeyFrame = isKeyFrame; self.totalChunks = totalChunks; self.totalSize = totalSize
    }

    public func serialize() -> Data {
        var d = Data(capacity: FrameHeaderPayload.size)
        var fid = frameId.littleEndian; d.append(Data(bytes: &fid, count: 4))
        var w = width.littleEndian;     d.append(Data(bytes: &w, count: 2))
        var h = height.littleEndian;    d.append(Data(bytes: &h, count: 2))
        var kf: UInt8 = isKeyFrame ? 1 : 0; d.append(Data(bytes: &kf, count: 1))
        var tc = totalChunks.littleEndian; d.append(Data(bytes: &tc, count: 2))
        // 1 byte padding
        var pad: UInt8 = 0; d.append(Data(bytes: &pad, count: 1))
        var ts = totalSize.littleEndian; d.append(Data(bytes: &ts, count: 4))
        return d
    }

    public static func deserialize(from data: Data) -> FrameHeaderPayload? {
        guard data.count >= size else { return nil }
        let fid = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let w = data.subdata(in: 4..<6).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let h = data.subdata(in: 6..<8).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let kf = data[8] != 0
        let tc = data.subdata(in: 9..<11).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let ts = data.subdata(in: 12..<16).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        return FrameHeaderPayload(frameId: fid, width: w, height: h, isKeyFrame: kf, totalChunks: tc, totalSize: ts)
    }
}

public struct FrameChunkPayload {
    public let frameId: UInt32
    public let chunkIndex: UInt16
    public let chunkData: Data

    public static let headerSize = 6

    public init(frameId: UInt32, chunkIndex: UInt16, chunkData: Data) {
        self.frameId = frameId; self.chunkIndex = chunkIndex; self.chunkData = chunkData
    }

    public func serialize() -> Data {
        var d = Data(capacity: FrameChunkPayload.headerSize + chunkData.count)
        var fid = frameId.littleEndian; d.append(Data(bytes: &fid, count: 4))
        var ci = chunkIndex.littleEndian; d.append(Data(bytes: &ci, count: 2))
        d.append(chunkData)
        return d
    }

    public static func deserialize(from data: Data) -> FrameChunkPayload? {
        guard data.count >= headerSize else { return nil }
        let fid = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let ci = data.subdata(in: 4..<6).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let chunk = data.subdata(in: headerSize..<data.count)
        return FrameChunkPayload(frameId: fid, chunkIndex: ci, chunkData: chunk)
    }
}

import Foundation

public enum InputEventType: UInt8 {
    case mouseMove = 0
    case leftMouseDown = 1
    case leftMouseUp = 2
    case rightMouseDown = 3
    case rightMouseUp = 4
    case scrollWheel = 5
    case keyDown = 6
    case keyUp = 7
    case flagsChanged = 8
    case leftMouseDragged = 9
    case rightMouseDragged = 10
}

public struct ModifierFlags: OptionSet {
    public let rawValue: UInt16
    public init(rawValue: UInt16) { self.rawValue = rawValue }

    public static let shift   = ModifierFlags(rawValue: 1 << 0)
    public static let control = ModifierFlags(rawValue: 1 << 1)
    public static let option  = ModifierFlags(rawValue: 1 << 2)
    public static let command = ModifierFlags(rawValue: 1 << 3)
    public static let capsLock = ModifierFlags(rawValue: 1 << 4)
}

public struct InputEventPayload {
    public let type: InputEventType
    public let x: Float
    public let y: Float
    public let keyCode: UInt16
    public let modifiers: ModifierFlags
    public let scrollDeltaX: Float
    public let scrollDeltaY: Float

    public static let size = 21

    public init(type: InputEventType, x: Float, y: Float, keyCode: UInt16 = 0,
                modifiers: ModifierFlags = [], scrollDeltaX: Float = 0, scrollDeltaY: Float = 0) {
        self.type = type; self.x = x; self.y = y; self.keyCode = keyCode
        self.modifiers = modifiers; self.scrollDeltaX = scrollDeltaX; self.scrollDeltaY = scrollDeltaY
    }

    public func serialize() -> Data {
        var d = Data(capacity: InputEventPayload.size)
        var t = type.rawValue; d.append(Data(bytes: &t, count: 1))
        var fx = x.bitPattern.littleEndian; d.append(Data(bytes: &fx, count: 4))
        var fy = y.bitPattern.littleEndian; d.append(Data(bytes: &fy, count: 4))
        var kc = keyCode.littleEndian; d.append(Data(bytes: &kc, count: 2))
        var mf = modifiers.rawValue.littleEndian; d.append(Data(bytes: &mf, count: 2))
        var sdx = scrollDeltaX.bitPattern.littleEndian; d.append(Data(bytes: &sdx, count: 4))
        var sdy = scrollDeltaY.bitPattern.littleEndian; d.append(Data(bytes: &sdy, count: 4))
        return d
    }

    public static func deserialize(from data: Data) -> InputEventPayload? {
        guard data.count >= size else { return nil }
        guard let t = InputEventType(rawValue: data[0]) else { return nil }
        let x = Float(bitPattern: data.subdata(in: 1..<5).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        let y = Float(bitPattern: data.subdata(in: 5..<9).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        let kc = data.subdata(in: 9..<11).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let mf = ModifierFlags(rawValue: data.subdata(in: 11..<13).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
        let sdx = Float(bitPattern: data.subdata(in: 13..<17).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        let sdy = Float(bitPattern: data.subdata(in: 17..<21).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        return InputEventPayload(type: t, x: x, y: y, keyCode: kc, modifiers: mf, scrollDeltaX: sdx, scrollDeltaY: sdy)
    }
}

import Foundation

public struct HandshakeCapabilities: OptionSet {
    public let rawValue: UInt64

    public init(rawValue: UInt64) {
        self.rawValue = rawValue
    }

    public static let streamConfiguration = HandshakeCapabilities(rawValue: 1 << 0)
    public static let clipboardSync = HandshakeCapabilities(rawValue: 1 << 1)
    public static let textClipboardSync = HandshakeCapabilities(rawValue: 1 << 2)
}

public struct HandshakePayload {
    public let hostname: String
    public let screenWidth: UInt16
    public let screenHeight: UInt16
    public let scaleFactor: Float
    public let protocolVersion: UInt8
    public let capabilities: HandshakeCapabilities

    public init(hostname: String, screenWidth: UInt16, screenHeight: UInt16, scaleFactor: Float, protocolVersion: UInt8 = ERDConstants.protocolVersion, capabilities: HandshakeCapabilities = []) {
        self.hostname = hostname
        self.screenWidth = screenWidth
        self.screenHeight = screenHeight
        self.scaleFactor = scaleFactor
        self.protocolVersion = protocolVersion
        self.capabilities = capabilities
    }

    public func serialize() -> Data {
        var data = Data()
        let nameData = hostname.data(using: .utf8) ?? Data()
        var nameLen = UInt16(nameData.count).littleEndian; data.append(Data(bytes: &nameLen, count: 2))
        data.append(nameData)
        var w = screenWidth.littleEndian; data.append(Data(bytes: &w, count: 2))
        var h = screenHeight.littleEndian; data.append(Data(bytes: &h, count: 2))
        var s = scaleFactor.bitPattern.littleEndian; data.append(Data(bytes: &s, count: 4))
        var version = protocolVersion; data.append(Data(bytes: &version, count: 1))
        var flags = capabilities.rawValue.littleEndian; data.append(Data(bytes: &flags, count: 8))
        return data
    }

    public static func deserialize(from data: Data) -> HandshakePayload? {
        guard data.count >= 2 else { return nil }
        var offset = 0
        let nameLen = Int(data.subdata(in: offset..<offset+2).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
        offset += 2
        guard nameLen <= 1024, data.count >= offset + nameLen + 8 else { return nil }
        let hostname = String(data: data.subdata(in: offset..<offset+nameLen), encoding: .utf8) ?? ""
        offset += nameLen
        let w = data.subdata(in: offset..<offset+2).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }; offset += 2
        let h = data.subdata(in: offset..<offset+2).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }; offset += 2
        let sBits = data.subdata(in: offset..<offset+4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let s = Float(bitPattern: sBits)
        offset += 4

        var protocolVersion = ERDConstants.legacyProtocolVersion
        var capabilities: HandshakeCapabilities = []
        if data.count >= offset + 9 {
            protocolVersion = data[offset]
            let flags = data.subdata(in: (offset + 1)..<(offset + 9)).withUnsafeBytes { $0.load(as: UInt64.self).littleEndian }
            capabilities = HandshakeCapabilities(rawValue: flags)
        }

        return HandshakePayload(hostname: hostname, screenWidth: w, screenHeight: h, scaleFactor: s, protocolVersion: protocolVersion, capabilities: capabilities)
    }
}

import Foundation

public enum ControlMessageType: UInt8 {
    case requestKeyFrame = 0
    case startStream = 1
    case stopStream = 2
    case disconnect = 3
    case ping = 4
    case pong = 5
    case bitrateAdjust = 6
    case streamConfigRequest = 7
    case streamConfigResponse = 8
    case streamConfigReject = 9
    case streamConfigError = 10
    case clipboardSyncRequest = 11
    case clipboardSyncUpdate = 12
    case clipboardSyncError = 13
}

public struct ControlMessage {
    public let type: ControlMessageType
    public let payload: Data?

    public init(type: ControlMessageType, payload: Data? = nil) {
        self.type = type
        self.payload = payload
    }

    public func serialize() -> Data {
        var d = Data([type.rawValue])
        if let payload = payload {
            d.append(payload)
        }
        return d
    }

    public static func deserialize(from data: Data) -> ControlMessage? {
        guard data.count >= 1, let t = ControlMessageType(rawValue: data[0]) else { return nil }
        let payload: Data? = data.count > 1 ? data.subdata(in: 1..<data.count) : nil
        return ControlMessage(type: t, payload: payload)
    }
}

public struct BitrateAdjustPayload {
    public let targetBitrate: Int32

    public static let size = 4

    public init(targetBitrate: Int32) {
        self.targetBitrate = targetBitrate
    }

    public func serialize() -> Data {
        var d = Data(capacity: BitrateAdjustPayload.size)
        var br = targetBitrate.littleEndian
        d.append(Data(bytes: &br, count: 4))
        return d
    }

    public static func deserialize(from data: Data) -> BitrateAdjustPayload? {
        guard data.count >= size else { return nil }
        let br = data.withUnsafeBytes { $0.load(as: Int32.self).littleEndian }
        return BitrateAdjustPayload(targetBitrate: br)
    }
}

public struct CursorUpdate {
    public let x: Float
    public let y: Float
    public let cursorType: UInt8

    public static let size = 9

    public init(x: Float, y: Float, cursorType: UInt8 = 0) {
        self.x = x; self.y = y; self.cursorType = cursorType
    }

    public func serialize() -> Data {
        var d = Data(capacity: CursorUpdate.size)
        var fx = x.bitPattern.littleEndian; d.append(Data(bytes: &fx, count: 4))
        var fy = y.bitPattern.littleEndian; d.append(Data(bytes: &fy, count: 4))
        var ct = cursorType; d.append(Data(bytes: &ct, count: 1))
        return d
    }

    public static func deserialize(from data: Data) -> CursorUpdate? {
        guard data.count >= size else { return nil }
        let x = Float(bitPattern: data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        let y = Float(bitPattern: data.subdata(in: 4..<8).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        return CursorUpdate(x: x, y: y, cursorType: data[8])
    }
}

public class AtomicBool {
    private let lock = NSLock()
    private var _value: Bool

    public init(_ value: Bool = false) { _value = value }

    public var value: Bool {
        get { lock.lock(); defer { lock.unlock() }; return _value }
        set { lock.lock(); defer { lock.unlock() }; _value = newValue }
    }
}

import Foundation

public struct StreamConfiguration {
    public let width: UInt32
    public let height: UInt32
    public let bitrate: UInt32
    public let framesPerSecond: UInt16

    public static let size = 14

    public init(width: UInt32, height: UInt32, bitrate: UInt32, framesPerSecond: UInt16) {
        self.width = width
        self.height = height
        self.bitrate = bitrate
        self.framesPerSecond = framesPerSecond
    }

    public func serialize() -> Data {
        var data = Data(capacity: Self.size)
        var w = width.littleEndian; data.append(Data(bytes: &w, count: 4))
        var h = height.littleEndian; data.append(Data(bytes: &h, count: 4))
        var b = bitrate.littleEndian; data.append(Data(bytes: &b, count: 4))
        var fps = framesPerSecond.littleEndian; data.append(Data(bytes: &fps, count: 2))
        return data
    }

    public static func deserialize(from data: Data) -> StreamConfiguration? {
        guard data.count >= size else { return nil }
        let width = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let height = data.subdata(in: 4..<8).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let bitrate = data.subdata(in: 8..<12).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let fps = data.subdata(in: 12..<14).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        return StreamConfiguration(width: width, height: height, bitrate: bitrate, framesPerSecond: fps)
    }
}

public enum StreamConfigurationErrorCode: UInt8 {
    case invalidRequest = 0
    case unsupportedDimensions = 1
    case unsupportedBitrate = 2
    case unsupportedFPS = 3
    case rejectedByPeer = 4
}

public struct StreamConfigurationRequestPayload {
    public let requestID: UInt32
    public let desiredConfiguration: StreamConfiguration

    public static let size = 4 + StreamConfiguration.size

    public init(requestID: UInt32, desiredConfiguration: StreamConfiguration) {
        self.requestID = requestID
        self.desiredConfiguration = desiredConfiguration
    }

    public func serialize() -> Data {
        var data = Data(capacity: Self.size)
        var id = requestID.littleEndian; data.append(Data(bytes: &id, count: 4))
        data.append(desiredConfiguration.serialize())
        return data
    }

    public static func deserialize(from data: Data) -> StreamConfigurationRequestPayload? {
        guard data.count >= size else { return nil }
        let requestID = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        guard let desiredConfiguration = StreamConfiguration.deserialize(from: data.subdata(in: 4..<data.count)) else { return nil }
        return StreamConfigurationRequestPayload(requestID: requestID, desiredConfiguration: desiredConfiguration)
    }
}

public struct StreamConfigurationResponsePayload {
    public let requestID: UInt32
    public let activeConfiguration: StreamConfiguration

    public static let size = 4 + StreamConfiguration.size

    public init(requestID: UInt32, activeConfiguration: StreamConfiguration) {
        self.requestID = requestID
        self.activeConfiguration = activeConfiguration
    }

    public func serialize() -> Data {
        var data = Data(capacity: Self.size)
        var id = requestID.littleEndian; data.append(Data(bytes: &id, count: 4))
        data.append(activeConfiguration.serialize())
        return data
    }

    public static func deserialize(from data: Data) -> StreamConfigurationResponsePayload? {
        guard data.count >= size else { return nil }
        let requestID = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        guard let activeConfiguration = StreamConfiguration.deserialize(from: data.subdata(in: 4..<data.count)) else { return nil }
        return StreamConfigurationResponsePayload(requestID: requestID, activeConfiguration: activeConfiguration)
    }
}

public struct StreamConfigurationRejectPayload {
    public let requestID: UInt32
    public let reason: StreamConfigurationErrorCode
    public let message: String

    public init(requestID: UInt32, reason: StreamConfigurationErrorCode, message: String) {
        self.requestID = requestID
        self.reason = reason
        self.message = message
    }

    public func serialize() -> Data {
        var data = Data()
        var id = requestID.littleEndian; data.append(Data(bytes: &id, count: 4))
        var code = reason.rawValue; data.append(Data(bytes: &code, count: 1))
        let messageData = message.data(using: .utf8) ?? Data()
        var length = UInt16(min(messageData.count, Int(UInt16.max))).littleEndian
        data.append(Data(bytes: &length, count: 2))
        data.append(messageData.prefix(Int(length)))
        return data
    }

    public static func deserialize(from data: Data) -> StreamConfigurationRejectPayload? {
        guard data.count >= 7 else { return nil }
        let requestID = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        guard let reason = StreamConfigurationErrorCode(rawValue: data[4]) else { return nil }
        let length = Int(data.subdata(in: 5..<7).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
        guard data.count >= 7 + length else { return nil }
        let message = String(data: data.subdata(in: 7..<(7 + length)), encoding: .utf8) ?? ""
        return StreamConfigurationRejectPayload(requestID: requestID, reason: reason, message: message)
    }
}

public struct StreamConfigurationErrorPayload {
    public let requestID: UInt32
    public let errorCode: StreamConfigurationErrorCode
    public let message: String

    public init(requestID: UInt32, errorCode: StreamConfigurationErrorCode, message: String) {
        self.requestID = requestID
        self.errorCode = errorCode
        self.message = message
    }

    public func serialize() -> Data {
        var data = Data()
        var id = requestID.littleEndian; data.append(Data(bytes: &id, count: 4))
        var code = errorCode.rawValue; data.append(Data(bytes: &code, count: 1))
        let messageData = message.data(using: .utf8) ?? Data()
        var length = UInt16(min(messageData.count, Int(UInt16.max))).littleEndian
        data.append(Data(bytes: &length, count: 2))
        data.append(messageData.prefix(Int(length)))
        return data
    }

    public static func deserialize(from data: Data) -> StreamConfigurationErrorPayload? {
        guard data.count >= 7 else { return nil }
        let requestID = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        guard let errorCode = StreamConfigurationErrorCode(rawValue: data[4]) else { return nil }
        let length = Int(data.subdata(in: 5..<7).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
        guard data.count >= 7 + length else { return nil }
        let message = String(data: data.subdata(in: 7..<(7 + length)), encoding: .utf8) ?? ""
        return StreamConfigurationErrorPayload(requestID: requestID, errorCode: errorCode, message: message)
    }
}

public enum ClipboardSyncDirection: UInt8 {
    case hostToClient = 0
    case clientToHost = 1
    case bidirectional = 2
}

public enum ClipboardSyncOrigin: UInt8 {
    case localPasteboard = 0
    case remotePasteboard = 1
    case syncedFromPeer = 2
}

public struct ClipboardSyncRequestPayload {
    public let requestID: UInt32
    public let direction: ClipboardSyncDirection
    public let origin: ClipboardSyncOrigin

    public static let size = 6

    public init(requestID: UInt32, direction: ClipboardSyncDirection, origin: ClipboardSyncOrigin) {
        self.requestID = requestID
        self.direction = direction
        self.origin = origin
    }

    public func serialize() -> Data {
        var data = Data(capacity: Self.size)
        var id = requestID.littleEndian; data.append(Data(bytes: &id, count: 4))
        var dir = direction.rawValue; data.append(Data(bytes: &dir, count: 1))
        var org = origin.rawValue; data.append(Data(bytes: &org, count: 1))
        return data
    }

    public static func deserialize(from data: Data) -> ClipboardSyncRequestPayload? {
        guard data.count >= size else { return nil }
        let requestID = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        guard let direction = ClipboardSyncDirection(rawValue: data[4]), let origin = ClipboardSyncOrigin(rawValue: data[5]) else { return nil }
        return ClipboardSyncRequestPayload(requestID: requestID, direction: direction, origin: origin)
    }
}

public struct ClipboardSyncUpdatePayload {
    public let requestID: UInt32
    public let direction: ClipboardSyncDirection
    public let origin: ClipboardSyncOrigin
    public let text: String

    public init(requestID: UInt32, direction: ClipboardSyncDirection, origin: ClipboardSyncOrigin, text: String) {
        self.requestID = requestID
        self.direction = direction
        self.origin = origin
        self.text = text
    }

    public func serialize() -> Data? {
        let textData = text.data(using: .utf8) ?? Data()
        guard textData.count <= ERDConstants.maxClipboardTextBytes else { return nil }
        var data = Data()
        var id = requestID.littleEndian; data.append(Data(bytes: &id, count: 4))
        var dir = direction.rawValue; data.append(Data(bytes: &dir, count: 1))
        var org = origin.rawValue; data.append(Data(bytes: &org, count: 1))
        var length = UInt16(textData.count).littleEndian; data.append(Data(bytes: &length, count: 2))
        data.append(textData)
        return data
    }

    public static func deserialize(from data: Data) -> ClipboardSyncUpdatePayload? {
        guard data.count >= 8 else { return nil }
        let requestID = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        guard let direction = ClipboardSyncDirection(rawValue: data[4]), let origin = ClipboardSyncOrigin(rawValue: data[5]) else { return nil }
        let length = Int(data.subdata(in: 6..<8).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
        guard length <= ERDConstants.maxClipboardTextBytes, data.count >= 8 + length else { return nil }
        let text = String(data: data.subdata(in: 8..<(8 + length)), encoding: .utf8) ?? ""
        return ClipboardSyncUpdatePayload(requestID: requestID, direction: direction, origin: origin, text: text)
    }
}

public struct ClipboardSyncErrorPayload {
    public let requestID: UInt32
    public let direction: ClipboardSyncDirection
    public let origin: ClipboardSyncOrigin
    public let errorCode: UInt8
    public let message: String

    public init(requestID: UInt32, direction: ClipboardSyncDirection, origin: ClipboardSyncOrigin, errorCode: UInt8, message: String) {
        self.requestID = requestID
        self.direction = direction
        self.origin = origin
        self.errorCode = errorCode
        self.message = message
    }

    public func serialize() -> Data {
        var data = Data()
        var id = requestID.littleEndian; data.append(Data(bytes: &id, count: 4))
        var dir = direction.rawValue; data.append(Data(bytes: &dir, count: 1))
        var org = origin.rawValue; data.append(Data(bytes: &org, count: 1))
        var code = errorCode; data.append(Data(bytes: &code, count: 1))
        let messageData = message.data(using: .utf8) ?? Data()
        var length = UInt16(min(messageData.count, Int(UInt16.max))).littleEndian
        data.append(Data(bytes: &length, count: 2))
        data.append(messageData.prefix(Int(length)))
        return data
    }

    public static func deserialize(from data: Data) -> ClipboardSyncErrorPayload? {
        guard data.count >= 9 else { return nil }
        let requestID = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        guard let direction = ClipboardSyncDirection(rawValue: data[4]), let origin = ClipboardSyncOrigin(rawValue: data[5]) else { return nil }
        let errorCode = data[6]
        let length = Int(data.subdata(in: 7..<9).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
        guard data.count >= 9 + length else { return nil }
        let message = String(data: data.subdata(in: 9..<(9 + length)), encoding: .utf8) ?? ""
        return ClipboardSyncErrorPayload(requestID: requestID, direction: direction, origin: origin, errorCode: errorCode, message: message)
    }
}

import Foundation
import Network

public class TCPChannel {
    private var connection: NWConnection?
    private var listener: NWListener?
    private let queue = DispatchQueue(label: "eclipticrd.tcp", qos: .userInteractive)
    private static let queueKey = DispatchSpecificKey<Bool>()
    private var receiveBuffer = Data()
    private var timeoutWorkItem: DispatchWorkItem?
    private var didNotifyDisconnect = false

    public var onConnect: (@Sendable () -> Void)?
    public var onDisconnect: (@Sendable () -> Void)?
    public var onReceive: (@Sendable (Data) -> Void)?

    public var remoteHostIP: String? {
        guard let endpoint = connection?.currentPath?.remoteEndpoint else { return nil }
        if case .hostPort(let host, _) = endpoint { return "\(host)" }
        return nil
    }

    public init() {
        queue.setSpecific(key: Self.queueKey, value: true)
    }

    deinit { stop() }

    // MARK: - Server side

    public func startListening(port: UInt16) throws {
        let params = NWParameters.tcp
        listener = try NWListener(using: params, on: NWEndpoint.Port(rawValue: port)!)
        listener?.newConnectionHandler = { [weak self] conn in
            self?.setupConnection(conn)
        }
        listener?.stateUpdateHandler = { state in
            ERDLog.network("[TCP] Listener state: \(state)")
        }
        listener?.start(queue: queue)
    }

    public func advertiseService(name: String) {
        listener?.service = NWListener.Service(name: name, type: ERDConstants.bonjourServiceType, domain: ERDConstants.bonjourDomain)
    }

    // MARK: - Client side

    public func connect(host: String, port: UInt16) {
        let endpoint = NWEndpoint.hostPort(host: NWEndpoint.Host(host), port: NWEndpoint.Port(rawValue: port)!)
        connect(to: endpoint)
    }

    public func connect(to endpoint: NWEndpoint) {
        let conn = NWConnection(to: endpoint, using: .tcp)
        queue.async { [weak self] in
            self?.setupConnection(conn)
        }
        setTimeout(ERDConstants.connectionTimeout)
    }

    public func connectICE(endpoints: [NWEndpoint]) {
        for endpoint in endpoints {
            let conn = NWConnection(to: endpoint, using: .tcp)
            conn.stateUpdateHandler = { [weak self] state in
                guard let self = self else { return }
                switch state {
                case .ready:
                    if self.connection == nil {
                        self.connection = conn
                        self.didNotifyDisconnect = false
                        self.cancelTimeout()
                        ERDLog.network("[Client] ICE Won by \(endpoint)")
                        conn.stateUpdateHandler = { [weak self] state in
                            switch state {
                            case .ready:
                                break
                            case .failed(let err):
                                ERDLog.error("[TCP] ICE connection failed: \(err)")
                                self?.notifyDisconnect()
                            case .cancelled:
                                self?.notifyDisconnect()
                            default:
                                break
                            }
                        }
                        self.startReceiving()
                        self.onConnect?()
                    } else {
                        conn.cancel()
                    }
                case .failed, .cancelled:
                    break
                default: break
                }
            }
            conn.start(queue: queue)
        }
        setTimeout(ERDConstants.connectionTimeout)
    }

    public func setTimeout(_ seconds: Double) {
        cancelTimeout()
        let work = DispatchWorkItem { [weak self] in
            guard let self = self else { return }
            ERDLog.error("[TCP] Connection timeout after \(seconds)s")
            self.connection?.cancel()
            self.connection = nil
            self.notifyDisconnect()
        }
        timeoutWorkItem = work
        queue.asyncAfter(deadline: .now() + seconds, execute: work)
    }

    // MARK: - Send

    public func send(_ data: Data) {
        // Length-prefixed framing: 4-byte little-endian length + payload
        var len = UInt32(data.count).littleEndian
        var frame = Data(bytes: &len, count: 4)
        frame.append(data)
        connection?.send(content: frame, completion: .contentProcessed { error in
            if let error = error {
                ERDLog.error("[TCP] Send error: \(error)")
            }
        })
    }

    public func sendControl(_ msg: ControlMessage) {
        let header = PacketHeader(type: .control, sequence: 0, timestamp: currentTimestamp())
        var packet = header.serialize()
        packet.append(msg.serialize())
        send(packet)
    }

    public func sendInput(_ input: InputEventPayload) {
        let header = PacketHeader(type: .inputEvent, sequence: 0, timestamp: currentTimestamp())
        var packet = header.serialize()
        packet.append(input.serialize())
        send(packet)
    }

    // MARK: - Stop

    public func stop() {
        let work = {
            self.cancelTimeout()
            self.connection?.cancel()
            self.connection = nil
            self.listener?.cancel()
            self.listener = nil
            self.receiveBuffer = Data()
            self.notifyDisconnect()
        }

        if DispatchQueue.getSpecific(key: Self.queueKey) == true {
            work()
        } else {
            queue.sync { work() }
        }
    }

    public func disconnectConnection() {
        let work = {
            self.cancelTimeout()
            self.connection?.cancel()
            self.connection = nil
            self.receiveBuffer = Data()
            self.notifyDisconnect()
        }

        if DispatchQueue.getSpecific(key: Self.queueKey) == true {
            work()
        } else {
            queue.sync { work() }
        }
    }

    // MARK: - Internal

    private func cancelTimeout() {
        timeoutWorkItem?.cancel()
        timeoutWorkItem = nil
    }

    private func setupConnection(_ conn: NWConnection) {
        connection = conn
        didNotifyDisconnect = false
        conn.stateUpdateHandler = { [weak self] state in
            switch state {
            case .ready:
                self?.cancelTimeout()
                ERDLog.network("[TCP] Connected to \(conn.endpoint)")
                self?.startReceiving()
                self?.onConnect?()
            case .failed(let err):
                ERDLog.error("[TCP] Connection failed: \(err)")
                self?.notifyDisconnect()
            case .cancelled:
                self?.notifyDisconnect()
            default: break
            }
        }
        conn.start(queue: queue)
    }

    private func notifyDisconnect() {
        guard !didNotifyDisconnect else { return }
        didNotifyDisconnect = true
        onDisconnect?()
    }

    private func startReceiving() {
        connection?.receive(minimumIncompleteLength: 1, maximumLength: 262144) { [weak self] content, _, isComplete, error in
            guard let self = self else { return }
            if let data = content {
                self.receiveBuffer.append(data)
                self.processBuffer()
            }
            if let error = error {
                ERDLog.error("[TCP] Receive error: \(error)")
                self.notifyDisconnect()
                return
            }
            if !isComplete {
                self.startReceiving()
            } else {
                self.notifyDisconnect()
            }
        }
    }

    private func processBuffer() {
        while receiveBuffer.count >= 4 {
            let length = Int(receiveBuffer.prefix(4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
            guard length > 0, length <= 16_777_216 else {
                // Invalid length — drop buffer to recover
                ERDLog.error("[TCP] Invalid frame length: \(length), dropping buffer")
                receiveBuffer.removeAll()
                break
            }
            guard receiveBuffer.count >= 4 + length else {
                break
            }
            let payload = receiveBuffer.subdata(in: 4..<(4 + length))
            receiveBuffer.removeSubrange(0..<(4 + length))
            onReceive?(payload)
        }
    }

    private func currentTimestamp() -> UInt32 {
        UInt32(truncatingIfNeeded: UInt64(Date().timeIntervalSince1970 * 1000))
    }
}

import Foundation
import Network

public class UDPChannel {
    private var connection: NWConnection?
    private var listener: NWListener?
    private let queue = DispatchQueue(label: "eclipticrd.udp", qos: .userInteractive)
    private static let queueKey = DispatchSpecificKey<Bool>()
    private var sequenceCounter: UInt32 = 0
    private let seqLock = NSLock()

    public var onReceive: (@Sendable (Data, NWEndpoint?) -> Void)?
    public var onReady: (@Sendable () -> Void)?

    private let _isReady = AtomicBool(false)
    public var isReady: Bool { _isReady.value }

    public init() {
        queue.setSpecific(key: Self.queueKey, value: true)
    }

    deinit { stop() }

    // MARK: - Server side

    public func startListening(port: UInt16) throws {
        let params = NWParameters.udp
        params.allowLocalEndpointReuse = true
        listener = try NWListener(using: params, on: NWEndpoint.Port(rawValue: port)!)
        listener?.newConnectionHandler = { [weak self] conn in
            guard let self = self else { return }
            self.connection = conn
            conn.stateUpdateHandler = { [weak self] state in
                if case .ready = state {
                    ERDLog.network("[UDP] Listener connection ready")
                    self?._isReady.value = true
                    self?.onReady?()
                }
            }
            conn.start(queue: self.queue)
            self.receiveLoop(on: conn)
        }
        listener?.start(queue: queue)
    }

    // MARK: - Client side

    public func connect(host: String, port: UInt16) {
        let endpoint = NWEndpoint.hostPort(host: NWEndpoint.Host(host), port: NWEndpoint.Port(rawValue: port)!)
        connect(to: endpoint)
    }

    public func connect(to endpoint: NWEndpoint) {
        let params = NWParameters.udp
        params.allowLocalEndpointReuse = true
        let conn = NWConnection(to: endpoint, using: params)
        queue.async { [weak self] in
            guard let self = self else { return }
            self.connection = conn
            conn.stateUpdateHandler = { [weak self] state in
                switch state {
                case .ready:
                    ERDLog.network("[UDP] Connected to \(endpoint)")
                    self?._isReady.value = true
                    self?.onReady?()
                case .failed(let e): ERDLog.error("[UDP] Connection failed: \(e)")
                default: break
                }
            }
            conn.start(queue: self.queue)
            self.receiveLoop(on: conn)
        }
    }

    // MARK: - Send

    public func send(_ data: Data, to endpoint: NWEndpoint? = nil) {
        guard let conn = connection else { return }
        conn.send(content: data, completion: .contentProcessed { error in
            if let error = error { ERDLog.error("[UDP] Send error: \(error)") }
        })
    }

    public func sendPacket(type: PacketType, payload: Data, to endpoint: NWEndpoint? = nil) {
        seqLock.lock()
        sequenceCounter += 1
        let seq = sequenceCounter
        seqLock.unlock()
        let ts = UInt32(truncatingIfNeeded: UInt64(Date().timeIntervalSince1970 * 1000))
        let header = PacketHeader(type: type, sequence: seq, timestamp: ts)
        var packet = header.serialize()
        packet.append(payload)
        send(packet, to: endpoint)
    }

    /// Send a small datagram to trigger the other side's listener to register us
    public func sendPing() {
        // Send 1-byte ping to trigger connection handler on the listener side
        send(Data([0xFF]))
    }

    // MARK: - Stop

    public func stop() {
        let work = {
            self.connection?.cancel()
            self.connection = nil
            self.listener?.cancel()
            self.listener = nil
            self.sequenceCounter = 0
            self._isReady.value = false
        }

        if DispatchQueue.getSpecific(key: Self.queueKey) == true {
            work()
        } else {
            queue.sync { work() }
        }
    }

    // MARK: - Internal

    private func receiveLoop(on conn: NWConnection) {
        conn.receiveMessage { [weak self] content, _, isComplete, error in
            guard let self = self else { return }
            if let data = content, data.count > 1 { // Ignore 1-byte pings
                self.onReceive?(data, conn.currentPath?.remoteEndpoint)
            }
            // Always re-arm for more data
            if conn.state == .ready {
                self.receiveLoop(on: conn)
            }
        }
    }
}

import Foundation

public struct SessionCandidate: Codable, Equatable {
    public let role: String
    public let localIP: String
    public let localPort: UInt16
    public let publicIP: String
    public let publicPort: UInt16

    public init(role: String, localIP: String, localPort: UInt16, publicIP: String, publicPort: UInt16) {
        self.role = role; self.localIP = localIP; self.localPort = localPort
        self.publicIP = publicIP; self.publicPort = publicPort
    }
}

public class SignalingClient {
    private let pin: String
    private let role: String
    private var webSocketTask: URLSessionWebSocketTask?
    private var isSearching = false
    private var pendingContinuation: CheckedContinuation<SessionCandidate, Error>?
    private var activeTask: URLSessionDataTask?
    private let lock = NSLock()

    public init(pin: String, role: String) {
        self.pin = pin
        self.role = role
    }

    deinit { stop() }

    public func exchangeCandidate(_ local: SessionCandidate) async throws -> SessionCandidate {
        // Post our candidate to ntfy.sh/<pin>
        let topicURL = URL(string: "https://ntfy.sh/eclipticrd-\(pin)")!

        let encoder = JSONEncoder()
        let payload = try encoder.encode(local)

        var postRequest = URLRequest(url: topicURL)
        postRequest.httpMethod = "POST"
        postRequest.httpBody = payload
        postRequest.setValue("application/json", forHTTPHeaderField: "Content-Type")

        ERDLog.network("[Signaling] Posting candidate to ntfy.sh/eclipticrd-\(pin)")
        let _ = try await URLSession.shared.data(for: postRequest)

        // Subscribe via SSE (Server-Sent Events) and wait for peer's candidate
        return try await withCheckedThrowingContinuation { continuation in
            lock.lock()
            isSearching = true
            pendingContinuation = continuation
            lock.unlock()

            var sseURL = URLComponents(url: topicURL.appendingPathComponent("json"), resolvingAgainstBaseURL: false)!
            sseURL.queryItems = [URLQueryItem(name: "poll", value: "1"), URLQueryItem(name: "since", value: "5m")]

            var request = URLRequest(url: sseURL.url!)
            request.timeoutInterval = 30

            let task = URLSession.shared.dataTask(with: request) { [weak self] data, _, error in
                guard let self = self else { return }

                self.lock.lock()
                guard self.isSearching else {
                    // Already cancelled via stop() — continuation was already resumed there
                    self.lock.unlock()
                    return
                }
                self.isSearching = false
                self.pendingContinuation = nil
                self.lock.unlock()

                if let error = error {
                    continuation.resume(throwing: error)
                    return
                }
                guard let data = data else {
                    continuation.resume(throwing: NSError(domain: "Signaling", code: 1, userInfo: [NSLocalizedDescriptionKey: "Signaling timeout waiting for peer"]))
                    return
                }

                // Parse JSON lines from ntfy.sh response
                let lines = String(data: data, encoding: .utf8)?.split(separator: "\n") ?? []
                let decoder = JSONDecoder()

                for line in lines.reversed() {
                    // Each line is a ntfy message JSON containing a "message" field
                    if let lineData = line.data(using: .utf8),
                       let ntfyMessage = try? JSONSerialization.jsonObject(with: lineData) as? [String: Any],
                       let messageStr = ntfyMessage["message"] as? String,
                       let messageData = messageStr.data(using: .utf8),
                       let candidate = try? decoder.decode(SessionCandidate.self, from: messageData),
                       candidate.role != self.role {
                        continuation.resume(returning: candidate)
                        return
                    }
                }

                continuation.resume(throwing: NSError(domain: "Signaling", code: 2, userInfo: [NSLocalizedDescriptionKey: "Signaling timeout waiting for peer"]))
            }
            activeTask = task
            task.resume()
        }
    }

    public func stop() {
        lock.lock()
        isSearching = false
        activeTask?.cancel()
        activeTask = nil
        let continuation = pendingContinuation
        pendingContinuation = nil
        lock.unlock()

        // Resume outside lock to avoid potential deadlock
        continuation?.resume(throwing: CancellationError())

        webSocketTask?.cancel(with: .goingAway, reason: nil)
        webSocketTask = nil
    }
}

import Foundation
import Network

public class STUNClient {
    private let serverHost: String
    private let serverPort: UInt16

    public init(serverHost: String = "stun.l.google.com", serverPort: UInt16 = 19302) {
        self.serverHost = serverHost
        self.serverPort = serverPort
    }

    public func fetchPublicIP() async throws -> (String, UInt16) {
        return try await withCheckedThrowingContinuation { continuation in
            let queue = DispatchQueue(label: "eclipticrd.stun")
            let endpoint = NWEndpoint.hostPort(host: NWEndpoint.Host(serverHost), port: NWEndpoint.Port(rawValue: serverPort)!)
            let params = NWParameters.udp
            if let ip = params.defaultProtocolStack.internetProtocol as? NWProtocolIP.Options {
                ip.version = .v4
            }
            let conn = NWConnection(to: endpoint, using: params)
            var completed = false

            func finish(result: Result<(String, UInt16), Error>) {
                guard !completed else { return }
                completed = true
                conn.cancel()
                switch result {
                case .success(let v): continuation.resume(returning: v)
                case .failure(let e): continuation.resume(throwing: e)
                }
            }

            conn.stateUpdateHandler = { [self] state in
                switch state {
                case .ready:
                    var request = Data(count: 20)
                    request[0] = 0x00; request[1] = 0x01
                    request[4] = 0x21; request[5] = 0x12; request[6] = 0xA4; request[7] = 0x42
                    for i in 8..<20 { request[i] = UInt8.random(in: 0...255) }

                    conn.send(content: request, completion: .contentProcessed { _ in })

                    conn.receiveMessage { data, _, _, error in
                        if let error = error {
                            finish(result: .failure(error))
                            return
                        }
                        guard let data = data, data.count >= 20 else {
                            finish(result: .failure(NSError(domain: "STUN", code: 1, userInfo: [NSLocalizedDescriptionKey: "Empty STUN response"])))
                            return
                        }
                        if let (ip, port) = Self.parseMappedAddress(from: data) {
                            finish(result: .success((ip, port)))
                        } else {
                            finish(result: .failure(NSError(domain: "STUN", code: 2, userInfo: [NSLocalizedDescriptionKey: "MAPPED-ADDRESS not found in STUN response"])))
                        }
                    }
                case .failed(let error):
                    finish(result: .failure(error))
                default:
                    break
                }
            }

            conn.start(queue: queue)

            queue.asyncAfter(deadline: .now() + 5.0) {
                finish(result: .failure(NSError(domain: "STUN", code: 3, userInfo: [NSLocalizedDescriptionKey: "STUN timeout"])))
            }
        }
    }

    private static func parseMappedAddress(from data: Data) -> (String, UInt16)? {
        let magicCookie: UInt32 = 0x2112A442
        var offset = 20 // Skip header

        while offset + 4 <= data.count {
            let attrType = UInt16(data[offset]) << 8 | UInt16(data[offset+1])
            let attrLen = Int(UInt16(data[offset+2]) << 8 | UInt16(data[offset+3]))
            offset += 4

            guard offset + attrLen <= data.count else { break }

            if attrType == 0x0020 { // XOR-MAPPED-ADDRESS
                guard attrLen >= 8 else { break }
                let family = data[offset + 1]
                let xPort = (UInt16(data[offset+2]) << 8 | UInt16(data[offset+3])) ^ UInt16(magicCookie >> 16)

                if family == 0x01 { // IPv4
                    let xAddr = UInt32(data[offset+4]) << 24 | UInt32(data[offset+5]) << 16 |
                                UInt32(data[offset+6]) << 8  | UInt32(data[offset+7])
                    let addr = xAddr ^ magicCookie
                    let ip = "\(addr >> 24 & 0xFF).\(addr >> 16 & 0xFF).\(addr >> 8 & 0xFF).\(addr & 0xFF)"
                    return (ip, xPort)
                }
            } else if attrType == 0x0001 { // MAPPED-ADDRESS (fallback)
                guard attrLen >= 8 else { break }
                let family = data[offset + 1]
                let port = UInt16(data[offset+2]) << 8 | UInt16(data[offset+3])

                if family == 0x01 {
                    let ip = "\(data[offset+4]).\(data[offset+5]).\(data[offset+6]).\(data[offset+7])"
                    return (ip, port)
                }
            }

            // Attributes are padded to 4-byte boundaries
            offset += (attrLen + 3) & ~3
        }
        return nil
    }
}

import Foundation
import Network

public class BonjourBrowser {
    public struct DiscoveredHost: Identifiable, Hashable, Equatable {
        public let id: String
        public let name: String
        public let endpoint: NWEndpoint

        public init(id: String, name: String, endpoint: NWEndpoint) {
            self.id = id; self.name = name; self.endpoint = endpoint
        }

        public var endpointDescription: String {
            switch endpoint {
            case .service(_, let type, let domain, _):
                return "\(type) (\(domain))"
            case .hostPort(let host, let port):
                return "\(host):\(port)"
            default:
                return "\(endpoint)"
            }
        }

        public func hash(into hasher: inout Hasher) { hasher.combine(id) }
        public static func == (lhs: DiscoveredHost, rhs: DiscoveredHost) -> Bool { lhs.id == rhs.id }
    }

    private var browser: NWBrowser?
    private let queue = DispatchQueue(label: "eclipticrd.bonjour")
    private var hosts: [DiscoveredHost] = []

    public var onHostsChanged: (@Sendable ([DiscoveredHost]) -> Void)?

    public init() {}

    public func startBrowsing() {
        let params = NWParameters()
        params.includePeerToPeer = true
        let descriptor = NWBrowser.Descriptor.bonjour(type: ERDConstants.bonjourServiceType, domain: ERDConstants.bonjourDomain)
        browser = NWBrowser(for: descriptor, using: params)

        browser?.browseResultsChangedHandler = { [weak self] results, _ in
            guard let self = self else { return }
            self.hosts = results.compactMap { result in
                if case .service(let name, _, _, _) = result.endpoint {
                    return DiscoveredHost(id: name, name: name, endpoint: result.endpoint)
                }
                return nil
            }
            ERDLog.network("[Bonjour] Found \(self.hosts.count) hosts")
            self.onHostsChanged?(self.hosts)
        }

        browser?.stateUpdateHandler = { state in
            if case .failed(let err) = state { ERDLog.error("[Bonjour] Browser failed: \(err)") }
        }

        browser?.start(queue: queue)
        ERDLog.network("[Bonjour] Browsing for services...")
    }

    public func stopBrowsing() {
        // Synchronize on queue to avoid data race with browseResultsChangedHandler
        queue.sync {
            browser?.cancel()
            browser = nil
            hosts = []
        }
    }
}

import Foundation
import AppKit

/// Monitors the system pasteboard for text changes and provides loop prevention
/// for bidirectional clipboard sync between host and client.
///
/// Loop prevention strategy:
/// - Tracks `changeCount` to detect local pasteboard changes
/// - When applying remote text, records the resulting changeCount to suppress the echo
/// - Uses content hash dedup to avoid sending identical text back
public class ClipboardMonitor {
    private let pasteboard = NSPasteboard.general
    private var pollTimer: DispatchSourceTimer?
    private let pollQueue = DispatchQueue(label: "eclipticrd.clipboard.poll")
    private let lock = NSLock()

    /// The changeCount after our last write, used to suppress echo
    private var lastWrittenChangeCount: Int = -1
    /// Hash of the last text we sent or applied, for content-level dedup
    private var lastTextHash: Int = 0
    /// Whether monitoring is active
    private var isRunning = false
    /// Last observed changeCount
    private var lastChangeCount: Int = 0

    private let onLocalChange: (String) -> Void

    /// - Parameter onLocalChange: Called when the local pasteboard text changes
    ///   (excluding changes applied via `applyRemoteText`).
    public init(onLocalChange: @escaping (String) -> Void) {
        self.onLocalChange = onLocalChange
    }

    public func start() {
        lock.lock()
        guard !isRunning else { lock.unlock(); return }
        isRunning = true
        lastChangeCount = pasteboard.changeCount
        lastWrittenChangeCount = -1
        lastTextHash = 0
        lock.unlock()

        let timer = DispatchSource.makeTimerSource(queue: pollQueue)
        timer.schedule(deadline: .now() + 0.5, repeating: 0.5)
        timer.setEventHandler { [weak self] in
            self?.poll()
        }
        timer.resume()
        pollTimer = timer
    }

    public func stop() {
        lock.lock()
        isRunning = false
        lock.unlock()
        pollTimer?.cancel()
        pollTimer = nil
    }

    /// Apply text received from the remote peer to the local pasteboard.
    /// The resulting changeCount is recorded so the next poll won't echo it back.
    public func applyRemoteText(_ text: String) {
        let hash = text.hashValue
        lock.lock()
        lastTextHash = hash
        lock.unlock()

        pasteboard.clearContents()
        pasteboard.setString(text, forType: .string)

        lock.lock()
        lastWrittenChangeCount = pasteboard.changeCount
        lastChangeCount = pasteboard.changeCount
        lock.unlock()
    }

    private func poll() {
        let currentCount = pasteboard.changeCount

        lock.lock()
        let running = isRunning
        let prevCount = lastChangeCount
        let writtenCount = lastWrittenChangeCount
        let prevHash = lastTextHash
        lock.unlock()

        guard running, currentCount != prevCount else { return }

        // Suppress echo: if this changeCount matches what we just wrote, skip
        if currentCount == writtenCount {
            lock.lock()
            lastChangeCount = currentCount
            lock.unlock()
            return
        }

        lock.lock()
        lastChangeCount = currentCount
        lock.unlock()

        guard let text = pasteboard.string(forType: .string), !text.isEmpty else { return }

        // Content-level dedup: don't send if identical to last sent/applied text
        let hash = text.hashValue
        guard hash != prevHash else { return }

        // Check size limit
        guard let textData = text.data(using: .utf8),
              textData.count <= ERDConstants.maxClipboardTextBytes else { return }

        lock.lock()
        lastTextHash = hash
        lock.unlock()

        onLocalChange(text)
    }
}

import Foundation

public enum NetworkUtils {
    /// Returns the local IPv4 address of a non-loopback network interface.
    /// Prefers en0 (WiFi) and en1 (Ethernet), but falls back to any active "en" interface
    /// to support USB-C adapters and other configurations.
    public static func getLocalIP() -> String? {
        var ifaddr: UnsafeMutablePointer<ifaddrs>?
        guard getifaddrs(&ifaddr) == 0, let firstAddr = ifaddr else { return nil }
        defer { freeifaddrs(ifaddr) }

        var preferred: String?
        var fallback: String?

        for ptr in sequence(first: firstAddr, next: { $0.pointee.ifa_next }) {
            let sa = ptr.pointee.ifa_addr.pointee
            guard sa.sa_family == UInt8(AF_INET) else { continue }
            let name = String(cString: ptr.pointee.ifa_name)
            guard name.hasPrefix("en") else { continue }

            var hostname = [CChar](repeating: 0, count: Int(NI_MAXHOST))
            getnameinfo(ptr.pointee.ifa_addr, socklen_t(sa.sa_len),
                        &hostname, socklen_t(hostname.count), nil, 0, NI_NUMERICHOST)
            let ip = String(cString: hostname)

            if name == "en0" || name == "en1" {
                preferred = ip
                break
            } else if fallback == nil {
                fallback = ip
            }
        }
        return preferred ?? fallback
    }
}

